DROP TABLE IF EXISTS `factura`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `factura` (
  `ID_FACTURA` int(11) NOT NULL AUTO_INCREMENT,
  `ID_RUTA` int(11) NOT NULL,
  `ID_CLIENTE` varchar(15) NOT NULL,
  `ID_USUARIO` int(11) NOT NULL,
  `ID_SUCURSAL` int(11) NOT NULL,
  `FA_FECHA` date NOT NULL,
  `FA_HORA` time NOT NULL,
  `FECHA_VIAJE` date DEFAULT NULL,
  `FA_CANTIDAD` int(11) NOT NULL,
  `FA_METODO` varchar(15) DEFAULT NULL,
  `FA_SUBTOTAL` decimal(10,2) NOT NULL,
  `FA_TOTAL` decimal(10,2) NOT NULL,
  `FA_DETALLE` text,
  `FA_TIPO` varchar(15) NOT NULL,
  `ESTADO` varchar(20) NOT NULL DEFAULT 'EMITIDA',
  PRIMARY KEY (`ID_FACTURA`),
  KEY `ID_RUTA` (`ID_RUTA`),
  KEY `ID_CLIENTE` (`ID_CLIENTE`),
  KEY `ID_USUARIO` (`ID_USUARIO`),
  KEY `ID_SUCURSAL` (`ID_SUCURSAL`),
  CONSTRAINT `factura_ibfk_1` FOREIGN KEY (`ID_RUTA`) REFERENCES `ruta` (`ID_RUTA`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `factura_ibfk_2` FOREIGN KEY (`ID_CLIENTE`) REFERENCES `cliente` (`ID_CLIENTE`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `factura_ibfk_3` FOREIGN KEY (`ID_USUARIO`) REFERENCES `usuario` (`ID_USUARIO`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `factura_ibfk_4` FOREIGN KEY (`ID_SUCURSAL`) REFERENCES `sucursal` (`ID_SUCURSAL`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

