CREATE TABLE `ruta_tramo` (
  `ID_RUTA_TRAMO` int(11) NOT NULL AUTO_INCREMENT,
  `ID_RUTA` int(11) NOT NULL,
  `ID_OPERADOR` int(11) DEFAULT NULL,
  `ID_TRAMO_CATALOGO` int(11) DEFAULT NULL,
  `ID_OFERTA` int(11) DEFAULT NULL COMMENT 'FK a OPERADOR_OFERTA_TRAMO',
  `ORDEN` int(11) NOT NULL,
  `DIA_DESFASE` tinyint(4) NOT NULL DEFAULT '0' COMMENT '0=mismo dia, 1=+1 dia, 2=+2 dias',
  `ORIGEN_TRAMO` varchar(100) DEFAULT NULL,
  `DESTINO_TRAMO` varchar(100) DEFAULT NULL,
  `OPERADOR` varchar(60) DEFAULT 'Propio',
  `PVP_TRAMO` decimal(10,2) DEFAULT '0.00',
  `COSTO_OPERADOR` decimal(10,2) DEFAULT '0.00',
  `UTILIDAD_AGENCIA` decimal(10,2) DEFAULT '0.00',
  `ADMITE_SOBREPESO` tinyint(1) DEFAULT '0',
  `LIMITE_EQUIPAJE_KG` decimal(10,2) DEFAULT '35.00',
  `PRECIO_SOBREPESO_KG` decimal(10,2) DEFAULT '1.00',
  `COSTO_SOBREPESO_KG` decimal(10,2) DEFAULT '0.00',
  `UTILIDAD_SOBREPESO_KG` decimal(10,2) DEFAULT '0.00',
  PRIMARY KEY (`ID_RUTA_TRAMO`),
  KEY `ID_RUTA` (`ID_RUTA`),
  KEY `idx_tramo_operador` (`ID_OPERADOR`),
  KEY `idx_rt_cat` (`ID_TRAMO_CATALOGO`),
  CONSTRAINT `ruta_tramo_ibfk_1` FOREIGN KEY (`ID_RUTA`) REFERENCES `ruta` (`ID_RUTA`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1764 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
